import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static int lilysHomework(List<Integer> arr) {int n = arr.size();List<Integer> sorted = new ArrayList<>(arr);Collections.sort(sorted);int swapsAsc = countSwaps(new ArrayList<>(arr), sorted);Collections.reverse(sorted);int swapsDesc = countSwaps(new ArrayList<>(arr), sorted);return Math.min(swapsAsc, swapsDesc);}private static int countSwaps(List<Integer> arr, List<Integer> target) {int n = arr.size();Map<Integer, Integer> map = new HashMap<>();for (int i = 0; i < n; i++) map.put(target.get(i), i);boolean[] visited = new boolean[n];int swaps = 0;for (int i = 0; i < n; i++) {if (visited[i] || arr.get(i).equals(target.get(i))) continue;int cycleSize = 0;int curr = i;while (!visited[curr]) {visited[curr] = true;curr = map.get(arr.get(curr));cycleSize++;}if (cycleSize > 0) swaps += (cycleSize - 1);}return swaps;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int n = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());int result = Result.lilysHomework(arr);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}